use lean_runtime::semantics::libm;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(Vec<f64>, Vec<f64>), n: u64) -> u64 {
    let (xs, ys) = (&inp.0[..], &inp.1[..]);
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            fbits(libm::pow(get_f64(xs, x >> 52), get_f64(ys, x >> 52))),
        );
    }
    acc
}

fn main() {
    run(
        || {
            f64_pairs(
                0x3F80000000000000,
                0x4020000000000000,
                0xC030000000000000,
                0x4040000000000000,
            )
        },
        kernel,
    )
}
